package com.bank.failfast;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class FailFastTest {

    // ═══ FAIL-FAST: CME on modification ═══
    @Test
    void failFast_throwsCME() {
        List<String> list = new ArrayList<>(List.of("SAV2001", "CUR3001", "FD4001"));
        assertThatThrownBy(() -> {
            for (String s : list) {
                if (s.equals("CUR3001")) list.remove(s);
            }
        }).isInstanceOf(ConcurrentModificationException.class);
    }

    // ═══ Iterator.remove() — safe ═══
    @Test
    void iteratorRemove_safe() {
        List<String> list = new ArrayList<>(List.of("SAV2001", "CUR3001", "FD4001"));
        Iterator<String> it = list.iterator();
        while (it.hasNext()) {
            if (it.next().equals("CUR3001")) it.remove();
        }
        assertThat(list).containsExactly("SAV2001", "FD4001");
    }

    // ═══ removeIf — safe (Java 8) ═══
    @Test
    void removeIf_safe() {
        List<String> list = new ArrayList<>(List.of("SAV2001", "CUR3001", "FD4001"));
        list.removeIf(s -> s.equals("CUR3001"));
        assertThat(list).containsExactly("SAV2001", "FD4001");
    }

    // ═══ FAIL-SAFE: ConcurrentHashMap — no CME ═══
    @Test
    void failSafe_noCME() {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
        map.put("A", 1); map.put("B", 2); map.put("C", 3);
        for (var entry : map.entrySet()) {
            map.remove(entry.getKey());  // NO CME!
        }
        assertThat(map).isEmpty();
    }

    // ═══ FAIL-SAFE: CopyOnWriteArrayList — snapshot ═══
    @Test
    void copyOnWrite_snapshot() {
        CopyOnWriteArrayList<String> list = new CopyOnWriteArrayList<>(List.of("A", "B", "C"));
        List<String> seen = new ArrayList<>();
        for (String s : list) {  // iterator on SNAPSHOT
            list.add("X");       // modifies LIVE list, not snapshot
            seen.add(s);
        }
        assertThat(seen).containsExactly("A", "B", "C");  // snapshot = original 3
        assertThat(list).hasSize(6);  // 3 original + 3 added during iteration
    }
}
