class TradeProcessor {
    // FAIL-FAST: structural change during iteration → CME
    List<Trade> batch = new ArrayList<>();
    void purgeCancelled() {
        // WRONG: for(Trade t: batch) if(cancel) batch.remove(t); // CME!
        batch.removeIf(Trade::isCancelled);      // safe (internal iter)
        // or explicit:
        Iterator<Trade> it = batch.iterator();
        while (it.hasNext()) if (it.next().isStale()) it.remove();
    }

    // FAIL-SAFE: weakly consistent, never throws CME
    Map<String,Trade> cache = new ConcurrentHashMap<>();
    void snapshotScan() {
        for (var e : cache.entrySet())           // may/may not see writes
            audit(e.getValue());                 // concurrent put() OK
    }
    // modCount: fail-fast collections bump it on add/remove;
    // next() compares expectedModCount → mismatch throws CME.
}
